using System.Buffers;
using System.Numerics;
using System.Runtime.InteropServices;

namespace CatalogSvc;

public class ProductCatalog
{
    private readonly Dictionary<string, string> _categories = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, double> _prices = new(StringComparer.OrdinalIgnoreCase);
    // Reverse index: category -> set of product codes
    private readonly Dictionary<string, HashSet<string>> _categoryIndex = new(StringComparer.OrdinalIgnoreCase);

    public void AddProduct(string code, string category, double price)
    {
        // Remove from old category index if re-categorizing
        if (_categories.TryGetValue(code, out var oldCategory))
        {
            if (_categoryIndex.TryGetValue(oldCategory, out var oldSet))
            {
                oldSet.Remove(code);
                if (oldSet.Count == 0)
                    _categoryIndex.Remove(oldCategory);
            }
        }

        _categories[code] = category;
        _prices[code] = price;

        ref var set = ref CollectionsMarshal.GetValueRefOrAddDefault(_categoryIndex, category, out bool exists);
        if (!exists)
            set = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        set!.Add(code);
    }

    public string? GetCategory(string code)
        => _categories.TryGetValue(code, out var cat) ? cat : null;

    /// <summary>
    /// Computes total price using SIMD-vectorized summation over a contiguous
    /// buffer of resolved prices. Uses Vector&lt;double&gt; to process multiple
    /// prices per CPU cycle on hardware with AVX2/AVX-512 support.
    /// </summary>
    public double GetTotalPrice(IEnumerable<string> codes)
    {
        // Resolve prices into a contiguous buffer for vectorized sum
        double[] rented = ArrayPool<double>.Shared.Rent(64);
        int count = 0;

        foreach (var code in codes)
        {
            if (_prices.TryGetValue(code, out var price))
            {
                if (count == rented.Length)
                {
                    var larger = ArrayPool<double>.Shared.Rent(rented.Length * 2);
                    rented.AsSpan(0, count).CopyTo(larger);
                    ArrayPool<double>.Shared.Return(rented);
                    rented = larger;
                }
                rented[count++] = price;
            }
        }

        double total = SimdSum(rented.AsSpan(0, count));
        ArrayPool<double>.Shared.Return(rented);
        return total;
    }

    /// <summary>
    /// Returns products by category in O(1) via reverse index instead of O(n) scan.
    /// </summary>
    public List<string> GetProductsByCategory(string category)
    {
        if (_categoryIndex.TryGetValue(category, out var set))
            return [.. set];
        return [];
    }

    /// <summary>
    /// SIMD-accelerated summation using hardware vector width.
    /// Processes Vector&lt;double&gt;.Count elements per iteration (e.g., 4 on AVX2, 8 on AVX-512).
    /// </summary>
    private static double SimdSum(ReadOnlySpan<double> values)
    {
        if (values.IsEmpty)
            return 0.0;

        int vectorSize = Vector<double>.Count;
        var span = MemoryMarshal.Cast<double, Vector<double>>(values[..(values.Length - values.Length % vectorSize)]);
        var accumulator = Vector<double>.Zero;

        for (int i = 0; i < span.Length; i++)
            accumulator += span[i];

        double total = Vector.Sum(accumulator);

        // Handle remaining elements that don't fill a full vector
        for (int i = values.Length - values.Length % vectorSize; i < values.Length; i++)
            total += values[i];

        return total;
    }
}

